using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    internal StateFingerprint TaskMemoWitnessKey(CombatPredictionSimulator sim)
    {
        SimulatedCombatState combat = (SimulatedCombatState)sim.State.CombatState;
        return BuildStateKey(combat.GetPlayerTurnNumber(_player), sim.State.GetCreature(_player.Creature),
            sim.State.GetPlayerCombatState(_player), combat, sim, sim.ShuffleEventCount,
            new HashSet<uint>());
    }
}

internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaskPathMemoContractAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        await ClearPlayerPilesAsync(player);
        await InjectCardAsync(live, player, new() { CardId = "INFLAME", Pile = "Hand" });
        await InjectCardAsync(live, player, new() { CardId = "INFLAME", UpgradeLevels = 1, Pile = "Hand" });
        await InjectCardAsync(live, player, new() { CardId = "BACKFLIP", Pile = "Hand" });
        await InjectCardAsync(live, player, new() { CardId = "BLADE_DANCE", Pile = "Hand" });
        await InjectCardAsync(live, player, new() { CardId = "BOUNCING_FLASK", Pile = "Hand" });
        foreach (string id in new[] { "WOUND", "DAZED", "STRIKE_SILENT" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Draw" });
        SetEnergy(player, 8);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        SolverDisplayNames names = SolverDisplayNames.Capture(live);
        SearchPolicySnapshot policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null);
        CombatBeamSolver driver = new(root, names, BattleDamageTracker.Observe(live), policy,
            potionPolicyOverride: SolverPotionPolicy.Disabled);
        CombatPredictionSimulator basis = root.ForkSimulator();
        Creature target = root.Enemies[0];
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(
            player, sim, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
        string Full(CombatPredictionSimulator sim) => State(sim) + "\nKEY=" + driver.TaskMemoWitnessKey(sim)
            + "\nHISTORY=" + CardContinuationContractHistoryText(sim)
            + "\nRNG=" + JsonSerializer.Serialize(new {
                sim.Rng.ShuffleState, sim.Rng.CombatCardGenerationState, sim.Rng.CombatPotionGenerationState,
                sim.Rng.CombatCardSelectionState, sim.Rng.CombatEnergyCostsState, sim.Rng.CombatTargetsState,
                sim.Rng.CombatOrbGenerationState, sim.Rng.MonsterAiState, sim.Rng.NicheState,
                sim.ShuffleEventCount, sim.TerminalStamp, sim.IsInProgress, sim.IsAboutToLose
            });
        string Route(CombatPredictionSimulator sim) => string.Join(">", sim.History
            .OfType<CombatPredictionCardPlayStartedEntry>().Select(e => e.Card.Id + "+" + e.Card.UpgradeLevel));
        CombatPredictionSimulator Replay(CombatPredictionSimulator parent, params string[] ids)
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator sim = parent.Fork();
            SimulatedCombatState combat = (SimulatedCombatState)sim.State.CombatState;
            ForkableSet<uint> deaths = [];
            foreach (string id in ids)
            {
                string[] parts = id.Split('+');
                PredictedCard card = sim.State.GetPlayerCombatState(player).Hand.Cards
                    .Single(c => c.Preview.Id.Entry == parts[0] && c.Preview.CurrentUpgradeLevel == int.Parse(parts[1]));
                using (combat.BeginCardExecutionScope(deaths))
                    if (!sim.ManualPlay(card, null, out _))
                        throw new InvalidOperationException("Witness card is not playable: " + id);
                if (!CorePowerSupport.ApplyEnemyDeathPowers(sim, combat, combat.KnownEnemies, deaths)
                    || !CombatBeamSolver.SettleReplayActionBoundary(sim, combat) || sim.HasPendingChoice)
                    throw new InvalidOperationException("Witness unexpectedly opened a choice.");
                sim.CheckWinCondition(root.StartTurnNumber);
            }
            return sim;
        }
        void Equal(string expected, string actual, string label)
        {
            if (expected != actual) throw new InvalidOperationException(label + " differs:\nEXPECTED\n"
                + expected + "\nACTUAL\n" + actual);
        }
        string Hash(string s) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));

        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        var memo = new TaskExactPathReplayMemo();
        SearchPolicySnapshot enabled = policy with { TaskReplayMemo = memo, VerifyIncrementalSearch = false, Interaction = null, IncludeTurnSetup = false, DevelopmentStrategy = null };
        CombatBeamSolver coldDriver = new(root, names, BattleDamageTracker.Observe(live), policy,
            searchProfile: policy.Profile, potionPolicyOverride: SolverPotionPolicy.Disabled);
        CombatBeamSolver hotDriver = new(root, names, BattleDamageTracker.Observe(live), enabled,
            searchProfile: policy.Profile, potionPolicyOverride: SolverPotionPolicy.Disabled);
        SearchNode Cold(CombatBeamSolver d, bool reversed = false) {
            SearchNode n = d.TaskMemoRoot();
            n = d.TaskMemoPlay(n, "INFLAME", reversed ? 1 : 0);
            n = d.TaskMemoPlay(n, "INFLAME", reversed ? 0 : 1);
            n = d.TaskMemoPlay(n, "BACKFLIP", 0);
            n = d.TaskMemoPlay(n, "BLADE_DANCE", 0);
            return d.TaskMemoPlay(n, "BOUNCING_FLASK", 0);
        }
        SearchNode cold = Cold(coldDriver);
        SearchNode first = Cold(hotDriver);
        _completedChecks.Add("ExactPathCardRiskInventory:" + JsonSerializer.Serialize(first.Snapshot.PredictionGaps));
        object[] held = memo.HoldTemplatesForTesting();
        if (held.Length != 5 || memo.Hits != 0 || memo.Published != 5)
            throw new InvalidOperationException($"Cold memo templates={held.Length} hits={memo.Hits} published={memo.Published} misses={memo.Misses} bypassed={memo.Bypassed}; rootRun={root.CapturedRunModSubscriberCount} rootCombat={root.CapturedCombatModSubscriberCount} baselib={root.CapturedBaseLibCardModifiers}; firstBoundary={first.Snapshot.BoundaryReason} firstRisk={first.Snapshot.HasRisk}");
        SearchNode hit = Cold(hotDriver);
        if (memo.Hits != 5) throw new InvalidOperationException("Identical full route did not hit five templates.");
        Equal(Full(cold.Snapshot.Simulator), Full(first.Snapshot.Simulator), "cold full prefix state/history/RNG");
        Equal(Full(cold.Snapshot.Simulator), Full(hit.Snapshot.Simulator), "hit full prefix state/history/RNG");
        hotDriver.TaskMemoCompare(hit, cold);
        SearchNode reversed = Cold(hotDriver, true);
        SearchNode reversedCold = Cold(coldDriver, true);
        if (memo.Hits != 5) throw new InvalidOperationException("Different same-state history route reused a template.");
        Equal(Full(reversedCold.Snapshot.Simulator), Full(reversed.Snapshot.Simulator), "different route cold fallback");
        if (Route(reversed.Snapshot.Simulator) == Route(hit.Snapshot.Simulator))
            throw new InvalidOperationException("Different prefix history was not preserved.");
        SearchNode opaque = first with { Parent = null, Action = null, ActionCount = 0 };
        if (memo.Input(opaque, new PlanAction(PlanActionKind.PlayCard, 1), "test") != null)
            throw new InvalidOperationException("Nonfresh origin was accepted.");

        SearchNode risky = Cold(coldDriver);
        risky.Snapshot.Simulator.History.RecordRisk(PredictionRiskReason.MethodNotMirrored);
        if (memo.Publish(new(0, "unknown-risk", risky.StateKey, 0, 0, "fixture"), risky.Snapshot))
            throw new InvalidOperationException("Unknown risk without a certified card OnPlay source was cached.");

        SolverSearchProfile alternate = policy.Profile with { BaseScoreOnly = true, BeamWidth = 7 };
        CombatBeamSolver altCold = new(root, names, BattleDamageTracker.Observe(live), policy,
            searchProfile: alternate, potionPolicyOverride: SolverPotionPolicy.Disabled);
        CombatBeamSolver altHot = new(root, names, BattleDamageTracker.Observe(live), enabled,
            searchProfile: alternate, potionPolicyOverride: SolverPotionPolicy.Disabled);
        SearchNode coldAlt = Cold(altCold), hitAlt = Cold(altHot);
        if (memo.Hits != 10) throw new InvalidOperationException("Same native path across profile did not reuse.");
        Equal(Full(coldAlt.Snapshot.Simulator), Full(hitAlt.Snapshot.Simulator), "alternate profile native state");
        altHot.TaskMemoCompare(hitAlt, coldAlt);
        if (BitConverter.DoubleToInt64Bits(hitAlt.Snapshot.Score) != BitConverter.DoubleToInt64Bits(coldAlt.Snapshot.Score))
            throw new InvalidOperationException("Current profile score was not recomputed.");

        string parentBefore = Full(hit.Snapshot.Simulator);
        CombatBeamSolver[] lanes = Enumerable.Range(0, 16).Select(_ => new CombatBeamSolver(root, names,
            BattleDamageTracker.Observe(live), enabled, potionPolicyOverride: SolverPotionPolicy.Disabled)).ToArray();
        SearchNode[] laneRoots = lanes.Select(d => d.TaskMemoRoot()).ToArray();
        await Task.WhenAll(lanes.Select((d, i) => Task.Run(() => {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            SearchNode n = d.TaskMemoPlay(laneRoots[i], "INFLAME", 0);
            n = d.TaskMemoPlay(n, "INFLAME", 1);
            n = d.TaskMemoPlay(n, "BACKFLIP", 0);
            n = d.TaskMemoPlay(n, "BLADE_DANCE", 0);
            n = d.TaskMemoPlay(n, "BOUNCING_FLASK", 0);
            Equal(Full(cold.Snapshot.Simulator), Full(n.Snapshot.Simulator), "parallel template hit " + i);
            ((SimulatedCombatState)n.Snapshot.Simulator.State.CombatState).Apply<StrengthPower>(
                player.Creature, i + 1, player.Creature);
            Equal(parentBefore, Full(hit.Snapshot.Simulator), "parallel source isolation " + i);
        })));
        if (memo.Hits != 90) throw new InvalidOperationException("Sixteen actual memo lanes did not all hit.");
        SearchNode after = Cold(hotDriver);
        Equal(parentBefore, Full(after.Snapshot.Simulator), "template remains unchanged after all hit mutations");
        Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "memo does not mutate live");
        GC.KeepAlive(held);
        CombatPredictionSimulator expected = Replay(basis, "INFLAME+0", "INFLAME+1", "BACKFLIP+0", "BLADE_DANCE+0", "BOUNCING_FLASK+0");
        using CancellationTokenSource deadline = new(TimeSpan.FromSeconds(12));
        foreach (string id in new[] { "INFLAME+0", "INFLAME+1", "BACKFLIP+0", "BLADE_DANCE+0", "BOUNCING_FLASK+0" })
        {
            string[] parts = id.Split('+');
            var liveCard = player.PlayerCombatState!.Hand.Cards.Single(c => c.Id.Entry == parts[0]
                && c.CurrentUpgradeLevel == int.Parse(parts[1]));
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction played
                    && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), liveCard),
                () => { if (!liveCard.TryManualPlay(null)) throw new InvalidOperationException("Native card not playable: " + id); },
                deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);
        }
        Equal(State(expected), ContinuationStamp.CaptureLive(live).StateText, "native full ordered state and RNG");
        AssertSnapshotEqual(CaptureSimulated(expected, (SimulatedCombatState)expected.State.CombatState,
            player, target), CaptureActual(live, player, target), "TRANSITION_PREFIX", "INFLAME_TWO_UPGRADES_BACKFLIP");
        _completedChecks.Add("ExactPathMemo:ActualColdHitMiss:GeneratedCards:RandomTargetRng:UnknownRiskRefused:SameStateDifferentPrefixMiss:CurrentProfileScore:OpaqueOriginRefused:SixteenConcurrentCacheForks:FullStateHistoryRng:ParentLiveIsolation");
        _completedChecks.Add($"ExactPathMemo:Hits={memo.Hits}:Published={memo.Published}:Bypassed={memo.Bypassed}:NativeState={Hash(State(expected))}");
    }
}

