using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;

namespace CombatSolver;

// Experimental, request-owned memo. It substitutes no search labels or scores.
internal sealed class TaskExactPathReplayMemo
{
    private const int EntryLimit = 8192, EdgeLimit = 65536;
    private readonly object _gate = new();
    private readonly ConditionalWeakTable<SimulationSnapshot, object> _fresh = new();
    private readonly ConditionalWeakTable<SearchNode, Box> _routes = new();
    private readonly Dictionary<(int Parent, string Action), Box> _edges = [];
    private readonly Dictionary<Key, Entry> _entries = [];
    private int _next;
    public long Hits, Misses, Published, Expired, Bypassed;
    internal readonly record struct Key(int Parent, string Action, StateFingerprint State,
        int HpLost, int RecoveredHp, string Policy);
    private sealed record Box(int Id, int Actions);
    private sealed record Template(CombatPredictionSimulator Simulator, uint[] Deaths, int Turn, int Shuffles);
    private sealed record Entry(WeakReference<Template> Template);

    internal void MarkFresh(SimulationSnapshot snapshot)
    { lock (_gate) if (!_fresh.TryGetValue(snapshot, out _)) _fresh.Add(snapshot, new()); }

    private Box Route(SearchNode parent)
    {
        if (_routes.TryGetValue(parent, out Box? cached)) return cached;
        Stack<SearchNode> pending = new();
        SearchNode cursor = parent;
        while (!_routes.TryGetValue(cursor, out cached))
        {
            pending.Push(cursor);
            if (cursor.Parent == null) break;
            cursor = cursor.Parent;
        }
        Box route = cached ?? new(0, 0);
        while (pending.TryPop(out SearchNode? node))
        {
            if (node.Parent == null)
                route = _fresh.TryGetValue(node.Snapshot, out _) && node.ActionCount == 0
                    && node.Action == null ? new(0, 0) : new(-1, 0);
            else if (route.Id >= 0)
            {
                if (node.Action == null) route = new(-1, 0);
                else
                {
                    var edge = (route.Id, JsonSerializer.Serialize(node.Action));
                    if (!_edges.TryGetValue(edge, out Box? next))
                    {
                        if (_edges.Count >= EdgeLimit) route = new(-1, 0);
                        else { next = new(++_next, route.Actions + 1); _edges.Add(edge, next); route = next; }
                    }
                    else route = next;
                }
                if (route.Id >= 0 && route.Actions != node.ActionCount) route = new(-1, 0);
            }
            _routes.Add(node, route);
        }
        return route;
    }

    internal Key? Input(SearchNode parent, PlanAction action, string replayPolicy)
    {
        lock (_gate)
        {
            Box route = Route(parent);
            if (route.Id < 0) { Bypassed++; return null; }
            return new(route.Id, JsonSerializer.Serialize(action), parent.StateKey,
                parent.Snapshot.CumulativePlayerHpLost, parent.Snapshot.RecoveredPlayerHp, replayPolicy);
        }
    }

    internal bool TryFork(Key key, out CombatPredictionSimulator? simulator, out uint[] deaths,
        out int turn, out int shuffles)
    {
        lock (_gate)
        {
            simulator = null; deaths = []; turn = shuffles = 0;
            if (!_entries.TryGetValue(key, out Entry? entry)) { Misses++; return false; }
            if (!entry.Template.TryGetTarget(out Template? template))
            { Expired++; _entries.Remove(key); Misses++; return false; }
            simulator = template.Simulator.Fork();
            deaths = template.Deaths; turn = template.Turn; shuffles = template.Shuffles;
            Hits++;
            return true;
        }
    }

    internal bool Publish(Key key, SimulationSnapshot result)
    {
        if (result.BoundaryReason != SearchBoundaryReason.None || result.HasRisk
            || result.PlayerDead || result.AllEnemiesDead || !CoveredCardRecords(result.Simulator)) return false;
        lock (_gate)
        {
            if (_entries.Count >= EntryLimit || _entries.ContainsKey(key)) return false;
            // A dedicated ordinary fork becomes a private immutable template. No source
            // snapshot or node is retained, and only this gate can fork the template.
            Template template = new(result.Simulator.Fork(), result.ProcessedEnemyDeaths.ToArray(),
                result.Turn, result.ShufflesCrossed);
            _entries.Add(key, new(new(template)));
            Published++;
            return true;
        }
    }

    // Exact existing card compensation inventory, never an assembly or namespace
    // default. Other risk kinds, sources, methods and custom spec registrations refuse.
    private static bool CoveredCardRecords(CombatPredictionSimulator simulator)
    {
        foreach (CombatPredictionRiskEntry entry in simulator.History.OfType<CombatPredictionRiskEntry>())
            if (entry.Reason is not (PredictionRiskReason.MethodNotMirrored or PredictionRiskReason.MethodMirrorIncomplete)
                || entry.Trace?.Invocation.Method?.Name != "OnPlay"
                || entry.Trace.Source is not MegaCrit.Sts2.Core.Models.CardModel card
                || !CardOnPlayCompensationCatalog.Contains(card)) return false;
        return true;
    }

    // Fixture only: make weak-cache hits deterministic without suppressing game GC.
    internal object[] HoldTemplatesForTesting()
    {
        lock (_gate) return _entries.Values.Select(entry => entry.Template.TryGetTarget(out Template? t)
            ? (object?)t : null).OfType<object>().ToArray();
    }
}

internal sealed partial class CombatBeamSolver
{
    private string? _taskMemoPolicy;
    private string TaskMemoPolicy => _taskMemoPolicy ??= JsonSerializer.Serialize(new {
        _potionPolicy, _potionStrategy, _forceAllPotionsDisabled, _enforcePotionDirectives,
        _maximumPotionUses, _minimumPotionUses, _earliestPotionTurn, _includeTurnSetup,
        _theftPolicy, _growthBudgets, _relicTargets, _ignoreLongTermRewards, _strategicBossHpRelief,
        policy.StateKeySalt, policy.PileOrderInvariantMask
    });

    private bool TaskCanMemo(PlanAction action, object? forkSeed, object? roundCapture, object? cardCapture)
        => policy.TaskReplayMemo != null && !policy.VerifyIncrementalSearch && !policy.IncludeTurnSetup
            && policy.DevelopmentStrategy == null && policy.Interaction == null
            && root.CapturedRunModSubscriberCount == 0 && root.CapturedCombatModSubscriberCount == 0
            && !root.CapturedBaseLibCardModifiers
            && forkSeed == null && roundCapture == null && cardCapture == null
            && _executionChoiceReplayCheckpoint == null && _cardChoiceReplayCheckpoint == null
            && _potionChoiceReplayCheckpoint == null && _roundReplayCheckpoint == null
            && action.Kind == PlanActionKind.PlayCard && !action.EndsPlayerTurn
            && action.Choice == null && action.NestedChoices is not { Count: > 0 }
            && action.TurnStartChoices is not { Count: > 0 } && action.RelicEffects is not { Count: > 0 }
            && action.ReplayCount == 0;

    private SimulationSnapshot TaskMemoSnapshot(CombatPredictionSimulator simulator, uint[] deaths,
        int turn, int shuffles, int actionCount)
    {
        ForkableSet<uint> ownedDeaths = [];
        foreach (uint id in deaths) ownedDeaths.Add(id);
        return Snapshot(simulator, turn, actionCount, shuffles, SearchBoundaryReason.None, ownedDeaths);
    }

    internal SearchNode TaskMemoRoot()
    {
        SimulationSnapshot s = Replay([]);
        return new(null, 0, s.PotionUseCount, s.PotionStrategicCost, s.Turn, SearchRouteTraits.None,
            0, s.Score, s.StateKey, s.HasRisk, s.BoundaryReason, false, null, s, CombatProgressState.Capture(s));
    }
    internal SearchNode TaskMemoPlay(SearchNode parent, string id, int upgrade)
    {
        PlanAction a = EnumeratePlannedCardActions(new ExpansionPlan(parent, CardNameFirst: false))
            .Single(x => x.Action.CardId == id && x.Action.CardUpgradeLevel == upgrade).Action;
        SimulationSnapshot s = ReplayAction(parent, a);
        return new(a, parent.ActionCount + 1, s.PotionUseCount, s.PotionStrategicCost, s.Turn,
            parent.Traits, parent.FutureSoldHp, s.Score, s.StateKey, s.HasRisk, s.BoundaryReason,
            s.AllEnemiesDead || s.PlayerDead, parent, s, CombatProgressState.Capture(s));
    }
    internal void TaskMemoCompare(SearchNode a, SearchNode b)
        => AssertIncrementalEquivalent(a.Action!, a.Actions, a.Snapshot, b.Snapshot);
}

